import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from '@/lib/utils'
import { Slot } from "radix-ui"

/*
 * GENERATED BY `shadcn add button`, WITH THIS APP'S OWN VARIANTS ADDED.
 *
 * It replaces six independently styled kinds of control: a theme toggle,
 * three date presets, two pager steps, two link-shaped buttons, a help dot
 * and a disclosure row. Each had restated the same four decisions -- a
 * border colour, a hover, a font and a cursor -- and, between them, defined
 * a focus style exactly once. Five of the six inherited the user agent's
 * ring, which nobody noticed because preflight is skipped and nothing resets
 * `outline`. The base class below is the one that now answers for all of
 * them, and `--color-ring` already maps to the blue `.row` had picked by hand.
 *
 * THREE THINGS HERE EXIST ONLY BECAUSE PREFLIGHT IS SKIPPED, and shadcn's
 * `Button` assumes it is not. Without the reset a `<button>` arrives wearing
 * the user agent's own chrome, and the variants below only paper over the
 * parts they happen to set:
 *
 *   appearance-none  `appearance: auto` is the platform widget look.
 *   border-0         the UA gives it `2px outset`, which is what made the
 *                    disclosure row two pixels taller -- a variant that sets
 *                    no border, like `ghost`, inherits the outset one.
 *   bg-transparent   and a `rgb(239,239,239)` background to go with it.
 *   [font-family:inherit]
 *                    and the browser's own font. Every one of the six rules
 *                    this replaces said `font: inherit`; the size and weight
 *                    come from a variant, so the family is the one part
 *                    nothing else supplies.
 *
 * `all: unset` was the old answer to the same problem, on one of the six.
 * These four are the answer that survives having utility classes.
 *
 * `cursor-pointer` is added and is NOT upstream's. Tailwind v4's preflight
 * does not set it on `<button>` and neither does shadcn's base, so every one
 * of these controls set it by hand. A cursor never appears in a screenshot,
 * so this one is asserted by computed style instead.
 *
 * Three project variants, because shadcn's nearest equivalents are all wrong
 * in the same direction -- they assume a filled button on a white app:
 *
 *   quiet   the theme toggle and the pager steps. `outline` is close but
 *           ships `bg-background shadow-xs` and a dark-mode `bg-input/30`.
 *   pill    a date preset. Pressed, not selected, and the comment that says
 *           why moved here with it.
 *   anchor  the operation and transaction links. `link` is `text-primary`
 *           (blue) underlined on hover; these are secondary ink with a
 *           PERMANENT bottom rule, which is a different control.
 */
const buttonVariants = cva(
  "inline-flex shrink-0 cursor-pointer appearance-none items-center justify-center gap-2 rounded-md border-0 bg-transparent [font-family:inherit] text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",

        /** A control that recedes until you reach for it. */
        quiet:
          "border border-border-strong bg-transparent text-secondary-text hover:border-secondary-text hover:text-primary-text",
        /** The same, on the page's own surface rather than transparent. */
        surface:
          "border border-border bg-surface-1 text-secondary-text hover:border-border-strong hover:text-primary-text",
        /*
         * Pressed state, not a separate "selected" class -- the button says
         * which one it is to assistive tech, and the styling follows that.
         * `data-state=on` is what a ToggleGroup sets; `aria-pressed` is what
         * a lone toggle sets; both are honoured so the look cannot drift
         * between the two.
         */
        pill:
          "rounded-full border border-border-strong bg-transparent text-secondary-text hover:border-secondary-text hover:text-primary-text aria-pressed:border-secondary-text aria-pressed:bg-surface-0 aria-pressed:font-semibold aria-pressed:text-primary-text data-[state=on]:border-secondary-text data-[state=on]:bg-surface-0 data-[state=on]:font-semibold data-[state=on]:text-primary-text",
        /** Reads as a link, is the colour of body text, underlined always. */
        anchor:
          "inline rounded-none border-0 border-b border-border-strong bg-transparent p-0 text-secondary-text no-underline hover:text-primary-text",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
        "icon-xs": "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-8",
        "icon-lg": "size-10",

        /** The sizes this app's own controls are, to the pixel. */
        toggle: "h-auto rounded-lg px-3 py-1.75 text-md font-normal",
        preset: "h-auto px-3 py-1 text-base font-normal",
        step: "h-auto px-2.5 py-1 text-base font-normal",
        /** A link sizes itself from the text it sits in. */
        inline: "h-auto text-base font-normal",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

/**
 * `type="button"` BY DEFAULT, which upstream does not do.
 *
 * It spreads onto a bare `<button>`, and the platform defaults that to
 * `submit`. There is no `<form>` in this app, so nothing breaks today and
 * nothing would warn when the first one arrives. All seven controls set it
 * by hand; here it is set once, and `...props` can still override it.
 */
function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const Comp = asChild ? Slot.Root : "button"

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      {...(asChild ? {} : { type: "button" as const })}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }
